enum LoadingState {
    case idle
    case loading
    case success(String)
}

func evaluateState(_ state: LoadingState) -> String {
    switch state {
    case .idle: "Ready"
    case .loading: "Fetching"
    case .success(let data): "Data: \(data)"
    }
}

