@MainActor
final class CacheSimulator {
    var inMemory: [String: String] = [:]

    func fetch(key: String) -> String {
        if let cached = inMemory[key] {
            return "Cached: \(cached)"
        }
        inMemory[key] = "RemoteData"
        return "Fetched: RemoteData"
    }
}

@MainActor
func testCache() {
    let sim = CacheSimulator()
    _ = sim.fetch(key: "user")
    let second = sim.fetch(key: "user")
    print(second)
}

testCache()

