enum FetchResult {
    case success(Int)
    case failure(String)
}

func summary(of result: FetchResult) -> String {
    switch result {
    case .success(let code): "Code: \(code)"
    case .failure(let msg): "Error: \(msg)"
    }
}

let res = FetchResult.success(200)
print(summary(of: res))

